WITH valid_payments AS (SELECT *, TRIM(status) AS clean_status FROM payments WHERE paid_at >= '2023-11-01'), summary AS (SELECT CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, AVG(amount) AS avg_amount, COUNT(DISTINCT amount) AS unique_methods FROM valid_payments GROUP BY CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT paid_cohort, avg_amount, unique_methods FROM summary
